const coverage = ctx.run.salary_coverage;
const amount = Number(get(ctx.subject.employment.terms, 'allowances.' + ctx.lookup.allowance + '.amount', 0));
const days = ctx.calendar_days;
const month_days = calendar_distance_days(month_start(coverage.from), month_end(coverage.to)) + 1;
// No work, no pay (DOLE Handbook on Workers' Statutory Monetary Benefits 2024 ch.1 §I): the allowance keeps the share of basic pay that unpaid days leave.
const basic = ctx.subtotals.BASIC;
// A monthly amount paid twice a month pays half each run (Labor Code art.103), whatever the month's length.
const frequency = get(ctx.subject.employer, 'payment_schedule.frequency', 'MONTHLY');
const share = frequency === 'SEMI_MONTHLY' ? 1 / 2 : frequency === 'TEN_DAY' ? 1 / 3 : days / month_days;
return basic > 0 ? Math.max(0, (amount * share * ctx.subtotals.BASIC_AFTER_UNPAID_LEAVE) / basic) : amount * share;

